 local booth=workspace:FindFirstChild("DJ Booth");if booth then sign(f,"DJ Sign",booth.CFrame*CFrame.new(0,3,-3.2),"DJ • BBYA 24/7",17);local dj=part(systems,"DJ Console",Vector3.new(8,1,3),booth.CFrame*CFrame.new(0,2,-1),Color3.fromRGB(35,25,48),Enum.Material.Metal);local pr=prompt(dj,"Hype Crowd","DJ Console",.3);pr.Triggered:Connect(function(plr)for _,p in ipairs(f:GetChildren())do if p:IsA("BasePart")and string.find(p.Name,"Neon")then p.Color=COLORS[math.random(1,#COLORS)]end end end)end
