local function queenTag(c)local h=c:FindFirstChild("Head")or c:WaitForChild("Head",10);if not h or h:FindFirstChild("BBYAQueenTag")then return end;local g=Instance.new("BillboardGui");g.Name="BBYAQueenTag";g.Size=UDim2.fromOffset(150,34);g.StudsOffset=Vector3.new(0,3,0);g.MaxDistance=45;g.Parent=h;local t=Instance.new("TextLabel");t.BackgroundTransparency=1;t.Size=UDim2.fromScale(1,1);t.Text="👑 RATU BBYA";t.Font=Enum.Font.GothamBold;t.TextColor3=Color3.fromRGB(255,220,90);t.TextScaled=true;t.Parent=g end
local function queenCommand(p,msg)if p.UserId~=BBYA_QUEEN_USER_ID or string.sub(msg,1,1)~="!"then return end;local a=string.split(msg," ");local c=string.lower(a[1]);if c=="!kick"then local t=findPlayer(a[2]);if t and t~=p then t:Kick("Removed by BBYA Queen")end elseif c=="!bring"then local t=findPlayer(a[2]);if t and t.Character and p.Character then t.Character:PivotTo(p.Character:GetPivot()*CFrame.new(3,0,0))end elseif c=="!goto"then local t=findPlayer(a[2]);if t and t.Character and p.Character then p.Character:PivotTo(t.Character:GetPivot()*CFrame.new(3,0,0))end elseif c=="!speed"then local h=p.Character and p.Character:FindFirstChildOfClass("Humanoid");if h then h.WalkSpeed=math.clamp(tonumber(a[2])or 32,16,80)end elseif c=="!normal"then local h=p.Character and p.Character:FindFirstChildOfClass("Humanoid");if h then h.WalkSpeed=16 end elseif c=="!day"then Lighting.ClockTime=14 elseif c=="!night"then night()elseif c=="!party"then for _,o in ipairs(workspace:GetDescendants())do if o:IsA("BasePart")and string.find(o.Name,"Neon")then o.Color=COLORS[math.random(1,#COLORS)]end end end end
